/* identical to playNearestMarkerSoundAtActor (matched), with its names changed by decompdecomp */
/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 playDistanceSound(u16, f32, M2C_UNK);               /* extern */
M2C_UNK updateSfxPanFromMarker(s32, s32, s32, M2C_UNK);      /* extern */
s32 randomIntBelow(M2C_UNK);                         /* extern */
f32 findNearestTrackMarker(s32, u16 *);                           /* extern */
extern M2C_UNK gMarkerSoundIds;
extern M2C_UNK gTrackMarkerParents;

/* Plays a random sound from gMarkerSoundIds at the nearest track marker's distance, then pans it to that marker. */ void playRandomMarkerSoundAtNearest(s32 source) {
    u16 markerIndex;
    f32 distance;

    distance = findNearestTrackMarker(source, &markerIndex);
    updateSfxPanFromMarker(playDistanceSound(*((u16 *)((s8 *)&gMarkerSoundIds + (randomIntBelow(3) * 2))), distance, 0xFF), *((M2C_UNK *)((s8 *)&gTrackMarkerParents + (markerIndex * 4))), source, 0);
}
